contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address token, uint256 amount, uint256 minUSDG) public payable {
        uint256 roundBefore = c.currentRound();
        bool reverted;
        // Top-level state-changing call wrapped in try/catch is disallowed, so instead
        // call it directly to observe revert via a guarded low-level pattern.
        // We must make a top-level statement: use try on a view-free call is forbidden,
        // so we perform the call directly and catch via assembly-free approach:
        bool success;
        bytes memory data = abi.encodeWithSelector(
            c.depositToken.selector, token, amount, minUSDG
        );
        (success, ) = address(c).call(data);
        reverted = !success;
        uint256 roundAfter = c.currentRound();
        assert(reverted && roundAfter == roundBefore);
    }
    receive() external payable {}
}

